#!/usr/bin/env node
/**
 * Quality gate: file size (CONTRACT §6)
 * -------------------------------------------------------------------------
 * Target:   ≤ 400 lines per hand-written source file  (soft target, WARNING)
 * Maximum: 550 lines per hand-written source file  (hard limit, ERROR)
 *
 * The physical line count is authoritative (identical to `wc -l`).
 *
 * Scope: all `*.ts` and `*.tsx` files under `src/` (hand-written).
 *
 * Exceptions (documented and justified):
 *
 *  1. Generated files are ignored. Detected via the header comment
 *     (`auto-generated`, `generated by`, `do not edit`, `@generated`).
 *     Affected: `src/data/songs/index.ts` — produced by
 *     `scripts/migrate_and_deduplicate.py`; the file must not be maintained
 *     by hand and is therefore not reviewable.
 *
 *  2. Known legacy files above the hard limit. These files already exceeded
 *     550 lines before the gate was introduced; they are documented as open
 *     backlog in `ARCHITECTURE.md` §6.1 and in `REQUIREMENTS.md`
 *     (NFR-009 / GAP-007). As long as the refactoring is not implemented
 *     they do not block the merge — but the gate reports them visibly on
 *     every run. If an exception file **grows** beyond the state recorded
 *     here, the gate reports a warning. Every *new* file above 550 lines is
 *     a hard error instead.
 *
 * Output: file, line count, limit, violation. Exit code 1 on error.
 *
 * Tolerance for concurrent work in the same repository:
 *   - files that disappear during the run are skipped
 *   - read errors are reported as a finding, not as a crash
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(SCRIPT_DIR, '..');
const SRC_DIR = path.join(REPO_ROOT, 'src');

/** Soft target: above that a warning. */
const SOFT_LIMIT = 400;
/** Hard maximum: above that an error (exit 1). */
const HARD_LIMIT = 550;

/**
 * Known legacy files above the hard limit (ARCHITECTURE.md §6.1,
 * REQUIREMENTS.md NFR-009 / GAP-007). Value = state at the time the gate
 * was introduced.
 * @type {Record<string, {lines: number, reason: string}>}
 */
const SIZE_EXCEPTIONS = {
  'src/utils/validate-song-data.ts': {
    lines: 502,
    reason:
      'Schema and limit checks (GAP-007): split into schema, limit and ' +
      'catalog validation',
  },
  'src/app/admin/review/page.tsx': {
    lines: 755,
    reason: 'Admin review page (GAP-007): split into song list + editor',
  },
  'src/app/lobby/page.tsx': {
    lines: 744,
    reason:
      'Lobby page (GAP-007): split into lobby, player list, mode selection',
  },
  'src/components/game/RevealPhase.tsx': {
    lines: 671,
    reason: 'Reveal phase (GAP-007): separate logic and rendering',
  },
  'src/stores/game-store.ts': {
    lines: 640,
    reason: 'State store (GAP-007): split into sub-stores',
  },
  'src/components/game/MusicPlayer.tsx': {
    lines: 630,
    reason: 'MusicPlayer (GAP-007): extract the provider adapter',
  },
  'src/components/game/modes/TimelineMode.tsx': {
    lines: 579,
    reason: 'Timeline mode (GAP-007): separate mode logic and UI',
  },
  'src/app/browse/page.tsx': {
    lines: 572,
    reason: 'Browse page (GAP-007): separate search field, list and filters',
  },
};

/** Markers that identify a generated file. */
const GENERATED_MARKERS = [
  /auto-?generated/i,
  /generated by/i,
  /do not edit/i,
  /@generated/i,
  /code generated/i,
];

/** Directories that are not traversed. */
const IGNORED_DIRS = new Set([
  'node_modules',
  '.next',
  'coverage',
  'out',
  '.git',
]);

/**
 * @param {string} dir
 * @param {string[]} [out]
 * @returns {string[]}
 */
function collectSourceFiles(dir, out = []) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (IGNORED_DIRS.has(entry.name)) continue;
      collectSourceFiles(full, out);
    } else if (entry.isFile() && /\.tsx?$/.test(entry.name)) {
      out.push(full);
    }
  }
  return out;
}

/**
 * Counts the physical lines (identical to `wc -l`).
 * @param {string} content
 * @returns {number}
 */
export function countLines(content) {
  if (content === '') return 0;
  const parts = content.split(/\r?\n/);
  return parts[parts.length - 1] === '' ? parts.length - 1 : parts.length;
}

/**
 * Checks whether a file is generated (header comment).
 * @param {string} content
 * @returns {boolean}
 */
export function isGenerated(content) {
  const head = content.slice(0, 2000);
  return GENERATED_MARKERS.some((marker) => marker.test(head));
}

/**
 * Runs the gate.
 * @returns {{
 *   files: number,
 *   generated: {file: string, lines: number}[],
 *   warnings: {file: string, lines: number, text: string}[],
 *   errors: {file: string, lines: number, text: string}[],
 *   notes: string[],
 *   ioErrors: string[]
 * }}
 */
export function runFileSizeCheck() {
  const files = collectSourceFiles(SRC_DIR);
  const generated = [];
  const warnings = [];
  const errors = [];
  const notes = [];
  const ioErrors = [];

  let checked = 0;

  for (const absolute of files) {
    const relative = path
      .relative(REPO_ROOT, absolute)
      .split(path.sep)
      .join('/');
    let content;
    try {
      content = fs.readFileSync(absolute, 'utf8');
    } catch (error) {
      ioErrors.push(
        `${relative}: file not readable (${error.code ?? error.message})`
      );
      continue;
    }

    const lines = countLines(content);
    checked += 1;

    if (isGenerated(content)) {
      generated.push({ file: relative, lines });
      continue;
    }

    const exception = SIZE_EXCEPTIONS[relative];

    if (lines > HARD_LIMIT) {
      if (exception) {
        // Known legacy file: report visibly, but do not block (see header).
        const delta = lines - exception.lines;
        notes.push(
          `${relative}: ${lines} lines — known legacy file above ${HARD_LIMIT} ` +
            `(exception, refactoring still open: ${exception.reason})` +
            (delta === 0
              ? ' — state unchanged'
              : ` — ${delta > 0 ? '+' : ''}${delta} lines versus the exception state (${exception.lines})`)
        );
        if (delta > 0) {
          warnings.push({
            file: relative,
            lines,
            text:
              `above the hard limit (${HARD_LIMIT}) and ${delta} lines more than the ` +
              `recorded exception state (${exception.lines}) — backlog is growing, ` +
              `refactoring still open: ${exception.reason}`,
          });
        }
      } else {
        errors.push({
          file: relative,
          lines,
          text: `above the hard limit (${HARD_LIMIT}) by ${lines - HARD_LIMIT} lines`,
        });
      }
      continue;
    }

    if (lines > SOFT_LIMIT) {
      warnings.push({
        file: relative,
        lines,
        text: `above the soft target (${SOFT_LIMIT}) by ${lines - SOFT_LIMIT} lines`,
      });
    }
  }

  // Exceptions that no longer exist or have shrunk
  const seen = new Set(
    files.map((f) => path.relative(REPO_ROOT, f).split(path.sep).join('/'))
  );
  for (const [file, exception] of Object.entries(SIZE_EXCEPTIONS)) {
    if (!seen.has(file)) {
      notes.push(
        `${file}: exception entry is stale (the file no longer exists).`
      );
    }
  }

  return { files: checked, generated, warnings, errors, notes, ioErrors };
}

// Only run when the file was started directly as a CLI.
const invokedDirectly =
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (invokedDirectly) {
  const result = runFileSizeCheck();

  console.log('Phomu quality gate: file size');
  console.log(`Source files checked under src/: ${result.files}`);
  console.log(
    `Limits: target ${SOFT_LIMIT} lines (warning), maximum ${HARD_LIMIT} lines (error)`
  );

  if (result.generated.length > 0) {
    console.log(`\nSkipped (generated): ${result.generated.length}`);
    for (const gen of result.generated) {
      console.log(`   ${gen.file} (${gen.lines} lines, generated)`);
    }
  }

  if (result.notes.length > 0) {
    console.log(
      `\nKnown legacy files (documented exceptions): ${result.notes.length}`
    );
    for (const note of result.notes) {
      console.log(`   ${note}`);
    }
  }

  if (result.warnings.length > 0) {
    console.log(`\n⚠️  ${result.warnings.length} warning(s):`);
    for (const warning of result.warnings) {
      console.log(
        `   ${warning.file}: ${warning.lines} lines — ${warning.text}`
      );
    }
  }

  if (result.ioErrors.length > 0) {
    console.log(`\n⚠️  ${result.ioErrors.length} read error(s):`);
    for (const ioError of result.ioErrors) {
      console.log(`   ${ioError}`);
    }
  }

  if (result.errors.length > 0) {
    console.error(
      `\n❌ ${result.errors.length} error(s) (above the maximum of ${HARD_LIMIT} lines):`
    );
    for (const error of result.errors) {
      console.error(`   ${error.file}: ${error.lines} lines — ${error.text}`);
    }
    process.exit(1);
  }

  console.log(
    `\n✅ Gate passed — 0 errors, ${result.warnings.length} warning(s), ` +
      `${result.notes.length} known legacy file(s).`
  );
  process.exit(0);
}
